import{_ as s,a0 as r,w as l,s as p,I as e,x as i,a1 as n,A as o,ao as b}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"完整指南：在 Linux 上使用 Calibre 創建電子書 | LCTT x X-CMD","titleTemplate":false,"description":"完整指南：在 Linux 上使用 Calibre 創建電子書 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"完整指南：在 Linux 上使用 Calibre 創建電子書 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"完整指南：在 Linux 上使用 Calibre 創建電子書 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161030 HOW TO CREATE AN EBOOK WITH CALIBRE IN LINUX","title":"完整指南：在 Linux 上使用 Calibre 創建電子書","tag":"201611","desc":""},"relativePath":"201611/20161030 HOW TO CREATE AN EBOOK WITH CALIBRE IN LINUX.md","filePath":"[post].md"}'),u={name:"201611/20161030 HOW TO CREATE AN EBOOK WITH CALIBRE IN LINUX.md"};function d(f,t,m,C,L,x){const a=r("Link");return l(),p("div",null,[t[21]||(t[21]=e("h1",{id:"完整指南-在-linux-上使用-calibre-創建電子書",tabindex:"-1"},[i("完整指南：在 Linux 上使用 Calibre 創建電子書 "),e("a",{class:"header-anchor",href:"#完整指南-在-linux-上使用-calibre-創建電子書","aria-label":"Permalink to “完整指南：在 Linux 上使用 Calibre 創建電子書”"},"​")],-1)),e("p",null,[n(a,{href:"https://itsfoss.com/wp-content/uploads/2016/10/Create-an-eBook-in-Linux.jpg"},{default:o(()=>[...t[0]||(t[0]=[e("img",{src:"https://itsfoss.com/wp-content/uploads/2016/10/Create-an-eBook-in-Linux.jpg",alt:"Guide to create an eBoook in Linux with Calibre"},null,-1)])]),_:1})]),t[22]||(t[22]=e("p",null,"摘要：這份初學者指南是告訴你如何在 Linux 上用 Calibre 工具快速創建一本電子書。",-1)),t[23]||(t[23]=e("p",null,"自從 Amazon（亞馬遜）在多年前開始銷售電子書，電子書已經有了質的飛躍發展並且變得越來越流行。好消息是電子書非常容易使用自由開源的工具來被創建。",-1)),t[24]||(t[24]=e("p",null,"在這個教程中，我會告訴你如何在 Linux 上創建一本電子書。",-1)),t[25]||(t[25]=e("h3",{id:"在-linux-上創建一本電子書",tabindex:"-1"},[i("在 Linux 上創建一本電子書 "),e("a",{class:"header-anchor",href:"#在-linux-上創建一本電子書","aria-label":"Permalink to “在 Linux 上創建一本電子書”"},"​")],-1)),e("p",null,[t[4]||(t[4]=i("要創建一本電子書，你可能需要兩個軟件：一個文本處理器（當然，我使用的是 ",-1)),n(a,{href:"https://www.libreoffice.org/"},{default:o(()=>[...t[1]||(t[1]=[i("LibreOffice",-1)])]),_:1}),t[5]||(t[5]=i("）和 Calibre 。",-1)),n(a,{href:"http://calibre-ebook.com/"},{default:o(()=>[...t[2]||(t[2]=[i("Calibre",-1)])]),_:1}),t[6]||(t[6]=i(" 是一個非常優秀的電子書閲讀器，也是一個電子書庫的程序。你可以使用它來",-1)),n(a,{href:"https://itsfoss.com/open-epub-books-ubuntu-linux/"},{default:o(()=>[...t[3]||(t[3]=[i("在 Linux 上打開 ePub 文件",-1)])]),_:1}),t[7]||(t[7]=i("或者管理你收集的電子書。（LCTT 譯註：LibreOffice 是 Linux 上用來處理文本的軟件，類似於 Windows 的 Office 軟件)",-1))]),t[26]||(t[26]=b('<p>除了這些軟件之外，你還需要準備一個電子書封面（1410×2250）和你的原稿。</p><h3 id="第一步" tabindex="-1">第一步 <a class="header-anchor" href="#第一步" aria-label="Permalink to “第一步”">​</a></h3><p>首先，你需要用你的文本處理器程序打開你的原稿。 Calibre 可以自動的為你創建一個書籍目錄。要使用到這個功能，你需要在你的原稿中設置每一章的標題樣式為 Heading 1，在 LibreOffice 中要做到這個只需要高亮標題並且在段落樣式下拉框中選擇“Heading 1”即可。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/header1.png" alt="ebook creation with Calibre"></p><p>如果你想要有子章節，並且希望他們也被加入到目錄中，只需要設置這些子章節的標題為 Heading 2。</p><p>做完這些之後，保存你的文檔為 HTML 格式文件。</p><h3 id="第二步" tabindex="-1">第二步 <a class="header-anchor" href="#第二步" aria-label="Permalink to “第二步”">​</a></h3><p>在 Calibre 程序裏面，點擊“添加書籍（Add books）”按鈕。在對話框出現後，你可以打開你剛剛存儲的 HTML 格式文件，將它加入到 Calibre 中。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre1.png" alt="create ebooks with Calibre"></p><h3 id="第三步" tabindex="-1">第三步 <a class="header-anchor" href="#第三步" aria-label="Permalink to “第三步”">​</a></h3><p>一旦這個 HTML 文件加入到 Calibre 庫中，選擇這個新文件並且點擊“編輯元數據（Edit Metadata）”按鈕。在這裏，你可以添加下面的這些信息：標題（Title)、 作者（Author）、封面圖片（cover image）、 描述（description）和其它的一些信息。當你填完之後，點擊“Ok”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre2.png" alt="creating ebooks with Calibre in Linux"></p><h3 id="第四步" tabindex="-1">第四步 <a class="header-anchor" href="#第四步" aria-label="Permalink to “第四步”">​</a></h3><p>現在點擊“轉換書籍（Covert books）”按鈕。</p><p>在新的窗口中，這裏會有一些可選項，但是你不會需要使用它們。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre3.png" alt="creating ebooks with Calibre in Linux -2"></p><p>在新窗口的右上部選擇框中，選擇 epub 文件格式。Calibre 也有創建 mobi 文件格式的其它選項，但是我發現創建那些文件之後經常出現我意料之外的事情。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre4.png" alt="creating ebooks with Calibre in Linux -3"></p><h3 id="第五步" tabindex="-1">第五步 <a class="header-anchor" href="#第五步" aria-label="Permalink to “第五步”">​</a></h3><p>在左邊新的對話框中，點擊“外觀（Look &amp; Feel）”。然後勾選中“移除段落間空白（Remove spacing between paragraphs）”</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre5.png" alt="creating ebooks with Calibre in Linux - 4"></p><p>接下來，我們會創建一個內容目錄。如果不打算在你的書中使用目錄，你可以跳過這個步驟。選中“內容目錄(Table of Contents）”標籤。接下來，點擊“一級目錄（Level 1 TOC (XPath expression））”右邊的魔術棒圖標。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre6.png" alt="creating ebooks with Calibre in Linux - 5"></p><p>在這個新的窗口中，在“匹配 HTML 標籤（Match HTML tags with tag name）”下的下拉菜單中選擇“h1”。點擊“OK” 來關閉這個窗口。如果你有子章節，在“二級目錄（Level 2 TOC (XPath expression)）”下選擇“h2”。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre7.png" alt="creating ebooks with Calibre in Linux - 6"></p><p>在我們開始生成電子書前，選擇輸出 EPUB 文件。在這個新的頁面，選擇“插入目錄（Insert inline Table of Contents）”選項。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre8.png" alt="creating ebooks with Calibre in Linux - 7"></p><p>現在你需要做的是點擊“OK”來開始生成電子書。除非你的是一個大文件，否則生成電子書的過程一般都完成的很快。</p><p>到此為止，你就已經創建一本電子書了。</p><p>對一些特別的用户比如他們知道如何寫 CSS 樣式文件（LCTT 譯註：CSS 文件可以用來美化 HTML 頁面)，Calibre 給了這類用户一個選項來為文章增加 CSS 樣式。只需要回到“外觀（Look &amp; Feel）”部分，選擇“風格（styling）”標籤選項。但如果你想創建一個 mobi 格式的文件，因為一些原因，它是不能接受 CSS 樣式文件的。</p><p><img src="https://itsfoss.com/wp-content/uploads/2016/10/calibre9.png" alt="creating ebooks with Calibre in Linux - 8"></p><p>好了，是不是感到非常容易？我希望這個教程可以幫助你在 Linux 上創建電子書。</p><hr>',33)),e("p",null,[t[9]||(t[9]=i("via: ",-1)),n(a,{href:"https://itsfoss.com/create-ebook-calibre-linux/"},{default:o(()=>[...t[8]||(t[8]=[i("https://itsfoss.com/create-ebook-calibre-linux/",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=i("作者：",-1)),n(a,{href:"https://itsfoss.com/author/john/"},{default:o(()=>[...t[10]||(t[10]=[i("John Paul",-1)])]),_:1}),t[14]||(t[14]=i(" 譯者：",-1)),n(a,{href:"https://github.com/chenzhijun"},{default:o(()=>[...t[11]||(t[11]=[i("chenzhijun",-1)])]),_:1}),t[15]||(t[15]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[12]||(t[12]=[i("wxy",-1)])]),_:1})]),e("p",null,[t[18]||(t[18]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[i("Linux中國",-1)])]),_:1}),t[20]||(t[20]=i(" 榮譽推出",-1))])])}const k=s(u,[["render",d]]);export{h as __pageData,k as default};
